import {
  createTreeview,
  type Treeview as TreeviewController,
  type TreeviewNode,
  type TreeviewOptions,
} from "@cssints/headless";
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { createEffect, For, merge, untrack } from "solid-js";

import { type PartProps, renderPart, type Renderable } from "./render.tsx";
import { t } from "./theme.ts" with { type: "cssints" };

/** The tree's state, as accessors: the roving node, and whether focus is inside the tree. */
export interface TreeviewState {
  readonly focus: () => number;
  readonly hasFocus: () => boolean;
}

/** What `render` gets: the props of the tree, `data-part` and the caller's class merged in. */
export type TreeviewPartProps = PartProps;

export interface TreeviewProps
  extends Omit<TreeviewOptions, "nodes" | "label">, Renderable<TreeviewPartProps, TreeviewState> {
  /** The nodes, in document order: `parent` is 0 for a root. */
  readonly nodes: ReadonlyArray<TreeviewNode>;
  /** The tree's name: a `role="tree"` needs one. */
  readonly label: string;
  readonly class?: string;
  /** The primitive, once: a page that moves the selection itself. */
  readonly onReady?: (tree: TreeviewController) => void;
}

// A tree is a list of rows. The primitive owns the roving tabindex, the expanded and selected flags and the ARIA that says
// where a row sits; the kit paints from those attributes and indents from `aria-level`. A flat list with `aria-level` is the
// pattern's other shape, and it is the one the primitive's per-node attributes describe.
const tree = css.cn(
  css.display("flex"),
  css.flexDirection("column"),
  css.gap("1px"),
  css.margin("0"),
  css.padding(t.space._1),
  css.listStyle("none"),
  css.borderRadius(t.radius.lg),
  css.bg(t.color.surface),
  css.fontSize(t.font.size),
  css.color(t.color.text),
);

const item = css.cn(
  // The row is the marker `within()` reads: its own `aria-expanded` is what the chevron follows, the
  // way a disclosure's trigger is.
  css.group(),
  css.display("flex"),
  // The primitive hides a row under a closed parent with the `hidden` attribute; the skin's own
  // `display` would otherwise override the UA's `[hidden] { display: none }` and paint it anyway.
  css.attr("hidden")(css.display("none")),
  css.alignItems("center"),
  css.gap(t.space._1),
  css.padding(t.space._1, t.space._2),
  css.borderRadius(t.radius.sm),
  css.cursor("pointer"),
  css.userSelect("none"),
  css.outline("none"),
  css.hover(css.bg(t.color.buttonBackground)),
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("-2px")),
  css.attr("aria-selected", "true")(css.bg(t.color.buttonBackground)),
  css.attr("aria-level", "2")(css.paddingInlineStart(t.space._5)),
  css.attr("aria-level", "3")(css.paddingInlineStart(t.space._7)),
);

const chevron = css.cn(
  css.display("inline-block"),
  css.width("1em"),
  css.color(t.color.muted),
  css.fontSize(t.font.sizeSm),
  css.transition("transform 120ms"),
  css.within(css.attr("aria-expanded", "true"))(css.transform("rotate(90deg)")),
);

/**
 * APG tree view: a `role="tree"` of rows whose levels, sizes and positions are the primitive's `aria-*`. Arrows, Home, End,
 * type-ahead and the roving tabindex are `createTreeview`'s; the kit syncs the DOM focus to the node it moved to, paints the
 * selected row, and turns the chevron with `aria-expanded`. A row deeper than the third level keeps the third level's indent.
 */
export const Treeview = (props: TreeviewProps): JSX.Element => {
  const treeControl = createTreeview({
    nodes: props.nodes,
    get multiSelectable() {
      return props.multiSelectable;
    },
    get value() {
      return props.value;
    },
    defaultValue: props.defaultValue,
    defaultExpanded: props.defaultExpanded,
    defaultSelected: props.defaultSelected,
    defaultFocus: props.defaultFocus,
    label: props.label,
    orientation: props.orientation,
    onExpandedChange: props.onExpandedChange,
    onSelectionChange: props.onSelectionChange,
    onValueChange: props.onValueChange,
    onActivate: props.onActivate,
  });
  untrack(() => props.onReady)?.(treeControl);

  let element: HTMLUListElement | undefined;
  // The primitive keeps the roving tabindex; real DOM focus is the host's to move to that row when focus is inside.
  createEffect(
    () => `${treeControl.hasFocus()}|${treeControl.focus()}`,
    () => {
      if (!treeControl.hasFocus()) {
        return;
      }
      const roving = element?.querySelector<HTMLElement>('[role="treeitem"][tabindex="0"]');
      if (roving !== null && roving !== undefined && document.activeElement !== roving) {
        roving.focus();
      }
    },
  );

  const own = {
    "data-part": "treeview",
    get class() {
      return css.cn(tree, props.class);
    },
  } as PartProps;
  const state: TreeviewState = { focus: treeControl.focus, hasFocus: treeControl.hasFocus };
  return renderPart(props, merge(treeControl.treeProps, own), state, (part) => (
    <ul
      {...part}
      ref={(node) => {
        element = node;
      }}
    >
      <For each={treeControl.nodeIds()}>
        {(id) => (
          <li {...treeControl.itemProps(id)} data-part="treeview-item" class={item}>
            <span aria-hidden="true" class={chevron}>
              {treeControl.isParent(id) ? "▸" : ""}
            </span>
            <span>{props.nodes.find((node) => node.id === id)?.label}</span>
          </li>
        )}
      </For>
    </ul>
  ));
};

import type { JSX } from "@solidjs/web";
import { untrack } from "solid-js";

/**
 * What a part hands to `render`: the props the part owns (`id`, `aria-*`, `data-part`, `class`) and the state it is in, as
 * accessors — Solid does not re-render a component, so a snapshot would be dead on the second read.
 *
 * Base UI's `render` takes an element and clones it with the part's props; Solid cannot clone (JSX is already a node), so
 * the element form becomes the function form and a component is that function: `render={(props) => <a {...props} />}`,
 * `render={Button}`.
 */
export type Render<P extends object, S> = (props: P, state: S) => JSX.Element;

/**
 * What a part hands to `render`: element-generic attributes, because the element is the caller's (`<a>`, `<textarea>`, a
 * component). `ref` stays the caller's too — a part cannot type a ref for an element it has not chosen.
 */
export type PartProps = Omit<JSX.HTMLAttributes<HTMLElement>, "ref"> & {
  readonly class?: string;
};

/** A part that anything can render: `render` replaces its element and keeps the props the part owns. */
export interface Renderable<P extends object, S> {
  readonly render?: Render<P, S> | undefined;
}

/**
 * Renders a part: the caller's `render` when it gave one, the part's own element otherwise. `render` is structural, so it is
 * read once (untracked): a part that swapped it at run time would need a remount, not an update.
 *
 * @param {Renderable<P, S>} part the component's props, for the `render` it may carry
 * @param {P} props the part's props, already merged with the caller's own and with `class` and `data-part`
 * @param {S} state the part's state, as accessors
 * @param {(props: P) => JSX.Element} fallback the element the part is by default
 * @returns {JSX.Element} the part
 */
export const renderPart = <P extends object, S>(
  part: Renderable<PartProps, S>,
  props: P,
  state: S,
  fallback: (props: P) => JSX.Element,
): JSX.Element => {
  const render = untrack(() => part.render);
  // the part hands more than `PartProps` (its own element's attributes: `type` on a button, `value` on an input); a render
  // function is typed by what every part guarantees, and reads the rest as the DOM attributes they are
  return render === undefined ? fallback(props) : render(props as PartProps, state);
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

export { t };

import { TREEVIEW_NODES, type Treeview as TreeviewController } from "@cssints/headless";
import {
  type TreeviewConfig,
  nodeToPath,
  pathToNode,
} from "@cssints/apg-specs/apg/treeview.bridge";
import type { Json } from "@cssints/apg-specs/scenario";
import type { Mounted } from "./treeview-driver.ts";
import { Treeview } from "./treeview.tsx";
import { createSignal } from "solid-js";
import { render } from "@solidjs/web";

export interface TreeviewMounted extends Mounted {
  readonly treeview: TreeviewController;
}

const idsOfMask = (mask: number): ReadonlyArray<number> =>
  [1, 2, 3, 4, 5, 6, 7].filter((id) => (mask & (1 << (id - 1))) !== 0);

/**
 * Mounts the styled tree for the scenario walk: the fixed seven-node tree of the spec, the
 * primitive it built through `onReady`, and the callback payloads the walk reads (one slash path per
 * node). Controlled, the fixture is the host: it keeps the selected node ids in a signal, passes
 * them as `value`, and either writes every request back (`accepts`) or ignores it.
 *
 * @param {TreeviewConfig} config the state the walk starts from and the host's policy
 * @returns {TreeviewMounted} the mounted tree and the driver's view of it
 */
export const mountTreeview = (config: TreeviewConfig): TreeviewMounted => {
  const root = document.createElement("div");
  document.body.append(root);
  const events = new Map<string, Json[]>();
  const push = (name: string, node: number): void => {
    events.set(name, [...(events.get(name) ?? []), nodeToPath(node)]);
  };
  const [host, setHost] = createSignal<ReadonlyArray<number>>(idsOfMask(config.selected));
  let api: TreeviewController | undefined;

  const writeHost = (next: ReadonlyArray<number>): void => {
    if (config.controlled) {
      setHost([...next].sort((a, b) => a - b));
    }
  };

  const dispose = render(
    () => (
      <Treeview
        nodes={TREEVIEW_NODES}
        label={config.label ?? "Files"}
        multiSelectable={config.multi}
        defaultExpanded={idsOfMask(config.expanded)}
        defaultValue={idsOfMask(config.selected)}
        defaultFocus={config.focus}
        value={config.controlled ? host() : undefined}
        orientation={config.orientation}
        onReady={(tree) => {
          api = tree;
        }}
        onValueChange={(selected) => {
          if (config.accepts) {
            setHost([...selected].sort((a, b) => a - b));
          }
        }}
        onExpandedChange={(node) => push("onExpandedChange", node.id)}
        onSelectionChange={(node) => push("onSelectionChange", node.id)}
        onActivate={(node) => push("onActivate", node.id)}
      />
    ),
    root,
  );

  return {
    root,
    events,
    setProp: (name, value) => {
      switch (name) {
        case "resetTypeahead":
          api?.resetTypeahead();
          return;
        case "selected":
        case "setValue":
          if (!Array.isArray(value)) {
            throw new Error(`selected needs an array, got ${JSON.stringify(value)}`);
          }
          writeHost(value.map((path) => pathToNode(String(path))));
          return;
        case "hostToggle":
          writeHost(host().includes(1) ? host().filter((id) => id !== 1) : [...host(), 1]);
          return;
        default:
          throw new Error(`fixture has no prop ${name}`);
      }
    },
    focus: () => (api?.hasFocus() === true ? nodeToPath(api.focus()) : null),
    dispose: () => {
      dispose();
      root.remove();
    },
    get treeview(): TreeviewController {
      if (api === undefined) {
        throw new Error("treeview fixture is not mounted");
      }
      return api;
    },
  };
};

import { type ActionStep, type Driver, type Json, Unsupported } from "@cssints/apg-specs/scenario";
import { flush } from "solid-js";
import { userEvent } from "vite-plus/test/browser";

/**
 * The generic DOM side of the scenario bridge. A pattern's fixture renders its
 * parts with `data-part="<name>"` and returns a `Mounted`; this turns scenario
 * steps into real pointer/keyboard input and DOM reads into observations.
 */
export interface Mounted {
  readonly root: HTMLElement;
  /** Apply a scenario `prop` step (programmatic input) to the mounted widget. */
  readonly setProp: (name: string, value: Json | undefined) => void;
  /** Callback payloads, recorded under their canonical name. */
  readonly events: ReadonlyMap<string, ReadonlyArray<Json>>;
  readonly value?: () => Json;
  /**
   * The part the primitive itself considers focused (`trigger`, `tab:1`), or
   * `null`. Preferred over `document.activeElement` so the walk does not race the
   * fixtures' deferred DOM focus (bean 209r).
   */
  readonly focus?: () => string | null;
  readonly dispose: () => void;
}

export interface DomDriverOptions {
  /** Parts that can be hidden: the ones `expect.visible` lists. */
  readonly hideableParts: ReadonlyArray<string>;
  readonly eventName?: (name: string) => string;
}

const BOOLEAN_ATTRS = new Set(["hidden", "disabled"]);
const REFERENCE_ATTRS = new Set([
  "aria-controls",
  "aria-labelledby",
  "aria-owns",
  "aria-activedescendant",
]);
const NAMED_KEYS = new Set(["Enter", "Tab", "Escape", "Backspace", "Delete", "Home", "End"]);

// Solid renders on its own schedule, but `flush()` applies the queued signal work
// synchronously; the fixtures then move DOM focus in a `setTimeout(0)` macrotask
// (kept for user-event's Enter semantics). Waiting one macrotask lets both land
// before the walk reads, without a frame — a frame also lets the browser's focus
// fixup run and perturb the observation (bean 209r). The walk reads focus from
// the fixture's primitive state when it offers one (`Mounted.focus`).
const settle = (): Promise<void> => {
  flush();
  return new Promise((resolve) => {
    setTimeout(resolve, 0);
  });
};

const keyboardSyntax = (key: string): string => {
  if (key === "Space" || key === " ") {
    return " ";
  }
  return NAMED_KEYS.has(key) || key.startsWith("Arrow") || key.startsWith("Page")
    ? `{${key}}`
    : key;
};

// A held key is always written by name: `{Space>}` keeps it down, `{/Space}`
// releases it wherever focus is at that moment (a blur between the two halves
// is exactly what a walk needs to see).
const keyName = (key: string) => (key === " " || key === "Space" ? "Space" : key);

/** `KeyboardEvent.key` uses a space character, not the `Space` alias. */
const eventKey = (key: string) => (key === "Space" ? " " : key);

const CLICKABLE_INPUT_TYPES = new Set([
  "button",
  "color",
  "file",
  "image",
  "reset",
  "submit",
  "checkbox",
  "radio",
]);

/**
 * A half press is dispatched directly (not through user-event's held-key state,
 * which auto-releases on a repeated down and leaks across walk drivers). The
 * two native activations user-event would otherwise add are emulated: Space
 * clicks a button-like element on keyup, Enter on keydown.
 */
const halfPress = (target: EventTarget | null, type: "keydown" | "keyup", key: string) => {
  if (!(target instanceof HTMLElement)) {
    return;
  }
  const keyValue = eventKey(key);
  const notPrevented = target.dispatchEvent(
    new KeyboardEvent(type, {
      key: keyValue,
      code: keyName(key),
      bubbles: true,
      cancelable: true,
    }),
  );
  const clickable =
    target.tagName === "BUTTON" ||
    (target instanceof HTMLInputElement && CLICKABLE_INPUT_TYPES.has(target.type));
  if (
    notPrevented &&
    clickable &&
    ((type === "keyup" && keyValue === " ") || (type === "keydown" && keyValue === "Enter"))
  ) {
    target.click();
  }
};

export const domDriver = (mounted: Mounted, options: DomDriverOptions): Driver => {
  const { root } = mounted;
  const canonical = options.eventName ?? ((name: string) => name);

  const partsOf = (name: string): HTMLElement[] => [
    ...root.querySelectorAll<HTMLElement>(`[data-part="${name}"]`),
  ];

  const targetOf = (element: HTMLElement): string => {
    const name = element.dataset["part"] ?? "";
    return `${name}:${partsOf(name).indexOf(element)}`;
  };

  const elementOf = (target: string): HTMLElement => {
    const [name = "", index = "0"] = target.split(":");
    const element = partsOf(name)[Number(index)];
    if (element === undefined) {
      throw new Unsupported(`part ${target}`);
    }
    return element;
  };

  const click = async (element: HTMLElement): Promise<void> => {
    // a disabled button is not actionable; force lets the browser drop the click itself
    await userEvent.click(element, { force: true });
  };

  // Half presses this driver dispatched a keydown for, so a stray `phase: "up"`
  // stays inert (the spec's key_up only fires on an armed press).
  const halfHeld = new Set<string>();

  return {
    perform: async (step: ActionStep) => {
      switch (step.event) {
        case "focus":
          elementOf(step.target ?? "").focus();
          break;
        case "blur":
          halfHeld.clear();
          elementOf(step.target ?? "").blur();
          break;
        case "click":
          await click(elementOf(step.target ?? ""));
          break;
        case "pointerdown":
          elementOf(step.target ?? "").focus();
          elementOf(step.target ?? "").dispatchEvent(
            new PointerEvent("pointerdown", {
              bubbles: true,
              cancelable: true,
              pointerType: step.pointerType ?? "mouse",
            }),
          );
          break;
        case "pointerup": {
          const element = elementOf(step.target ?? "");
          element.dispatchEvent(
            new PointerEvent("pointerup", {
              bubbles: true,
              cancelable: true,
              pointerType: step.pointerType ?? "mouse",
            }),
          );
          // a released pointer button is a click, as the browser would deliver it
          element.click();
          break;
        }
        case "pointercancel":
          elementOf(step.target ?? "").dispatchEvent(
            new PointerEvent("pointercancel", {
              bubbles: true,
              cancelable: true,
              pointerType: step.pointerType ?? "mouse",
            }),
          );
          break;
        case "hover":
          await userEvent.hover(elementOf(step.target ?? ""));
          break;
        case "unhover":
          await userEvent.unhover(elementOf(step.target ?? ""));
          break;
        case "key": {
          if (step.phase === "down") {
            const element = elementOf(step.target ?? "");
            if (document.activeElement !== element) {
              element.focus();
            }
            // a disabled/read-only control never arms (the spec's spaceArms
            // guard), so a later `up` must not activate it either
            const blocked =
              element.getAttribute("aria-disabled") === "true" ||
              element.getAttribute("aria-readonly") === "true" ||
              (element instanceof HTMLButtonElement && element.disabled);
            if (!blocked) {
              halfHeld.add(keyName(step.key ?? ""));
            }
            halfPress(element, "keydown", step.key ?? "");
            break;
          }
          if (step.phase === "up") {
            if (!halfHeld.delete(keyName(step.key ?? ""))) {
              break;
            }
            // release wherever focus went: deliberately do NOT re-focus the
            // target, or a keydown -> blur -> keyup walk would be defeated
            const active = document.activeElement;
            halfPress(
              active instanceof HTMLElement ? active : document.body,
              "keyup",
              step.key ?? "",
            );
            break;
          }
          const element = elementOf(step.target ?? "");
          if (document.activeElement !== element) {
            element.focus();
          }
          // a whole press releases the key, so a later `phase: "up"` is inert
          halfHeld.delete(keyName(step.key ?? ""));
          await userEvent.keyboard(keyboardSyntax(step.key ?? ""));
          break;
        }
        case "prop":
          if (step.set !== undefined) {
            for (const [name, value] of Object.entries(step.set)) {
              mounted.setProp(name, value);
              if ((name === "disabled" || name === "isDisabled") && value === true) {
                // the spec drops a pending press when the control disables
                halfHeld.clear();
              }
            }
          } else {
            mounted.setProp(step.prop ?? "", step.value);
            if ((step.prop === "disabled" || step.prop === "isDisabled") && step.value === true) {
              halfHeld.clear();
            }
          }
          break;
        default:
          throw new Unsupported(`event ${step.event}`);
      }
      await settle();
    },
    observer: {
      focus: () => {
        // Prefer the primitive's own focus: the fixtures sync DOM focus in a
        // deferred macrotask (kept for user-event's Enter semantics), so reading
        // `document.activeElement` here races that (bean 209r).
        if (mounted.focus !== undefined) {
          return mounted.focus();
        }
        const active = document.activeElement;
        const part =
          active instanceof HTMLElement ? active.closest<HTMLElement>("[data-part]") : null;
        return part !== null && root.contains(part) ? targetOf(part) : null;
      },
      attr: (target, name) => {
        if (name.startsWith("data-")) {
          throw new Unsupported(`styling hook ${name}`);
        }
        const value = elementOf(target).getAttribute(name);
        if (value === null) {
          return null;
        }
        if (value === "" && BOOLEAN_ATTRS.has(name)) {
          return "true";
        }
        if (REFERENCE_ATTRS.has(name)) {
          const referenced = root.querySelector<HTMLElement>(`[id="${value}"]`);
          return referenced?.dataset["part"] === undefined ? value : targetOf(referenced);
        }
        return value;
      },
      visible: () =>
        options.hideableParts.flatMap((name) =>
          partsOf(name)
            .filter((element) => element.checkVisibility())
            .map(targetOf),
        ),
      events: (name) => mounted.events.get(canonical(name)) ?? [],
      ...(mounted.value === undefined ? {} : { value: mounted.value }),
    },
    dispose: mounted.dispose,
  };
};

import {
  type ActionStep,
  type Driver,
  type ScenarioConfig,
  ScenarioMismatch,
  differentialWalk,
  parseScenarioFile,
  replayScenario,
  specDriver,
} from "@cssints/apg-specs/scenario";
import { TREEVIEW_NODES } from "@cssints/headless";
import { nodeToPath, pathToNode } from "@cssints/apg-specs/apg/treeview.bridge";
import { decodeDefinition, makeReferenceModel } from "@quint-machine/core";
import { afterEach, describe, expect, it } from "vite-plus/test";
import {
  treeviewBridge,
  treeviewConfig,
  treeviewProbe,
  treeviewSteps,
} from "@cssints/apg-specs/apg/treeview.bridge";
import apg from "@cssints/apg-specs/scenarios/apg/treeview.apg.json";
import definitionJson from "@cssints/apg-specs/apg/treeview.model.json";
import { type TreeviewMounted, mountTreeview } from "./treeview.fixture";
import { flush } from "solid-js";
import { userEvent } from "vite-plus/test/browser";

const model = makeReferenceModel(decodeDefinition(definitionJson));

const NAMED_KEYS = new Set(["Enter", "Home", "End"]);

const keyboardSyntax = (key: string): string => {
  if (key === "Space" || key === " ") {
    return " ";
  }
  return NAMED_KEYS.has(key) || key.startsWith("Arrow") ? `{${key}}` : key;
};

const settle = (): Promise<void> =>
  new Promise((resolve) => {
    requestAnimationFrame(() => {
      setTimeout(resolve, 0);
    });
  });

/**
 * The DOM side of the treeview scenario bridge. The scenario names a row by its slash path
 * (`treeitem:0/1`); the skin paints one part for every row, in document order, so the path resolves
 * to that node's position in `TREEVIEW_NODES`. `type` / `typeaheadReset` reach the primitive's
 * type-ahead directly.
 */
const treeviewDriver = (mounted: TreeviewMounted, consumeEvents: boolean): Driver => {
  const { root, treeview } = mounted;
  const consumed = new Map<string, number>();

  const items = (): HTMLElement[] => [
    ...root.querySelectorAll<HTMLElement>('[data-part="treeview-item"]'),
  ];
  const tree = (): HTMLElement => {
    const element = root.querySelector<HTMLElement>('[data-part="treeview"]');
    if (element === null) {
      throw new Error("no treeview part");
    }
    return element;
  };
  const elementOf = (target: string): HTMLElement => {
    if (target === "" || target === "tree") {
      return tree();
    }
    const id = pathToNode(target);
    const element = items()[TREEVIEW_NODES.findIndex((node) => node.id === id)];
    if (element === undefined) {
      throw new Error(`unknown part ${target}`);
    }
    return element;
  };
  const pathOf = (element: HTMLElement): string | null => {
    const node = TREEVIEW_NODES[items().indexOf(element)];
    return node === undefined ? null : nodeToPath(node.id);
  };
  const roving = (): HTMLElement | null =>
    tree().querySelector<HTMLElement>('[role="treeitem"][tabindex="0"]');
  const focusTarget = (target: string): void => {
    if (target === "" || target === "tree") {
      roving()?.focus();
      return;
    }
    elementOf(target).focus();
  };

  return {
    perform: async (step: ActionStep) => {
      switch (step.event) {
        case "focus":
          focusTarget(step.target ?? "tree");
          break;
        case "blur": {
          const active = document.activeElement;
          if (active instanceof HTMLElement && root.contains(active)) {
            active.blur();
          } else {
            roving()?.blur();
          }
          break;
        }
        case "click": {
          const element = elementOf(step.target ?? "");
          // Like the spec: an unreachable (hidden) node ignores the click, but
          // the type-ahead buffer still resets.
          if (!element.checkVisibility()) {
            element.click();
            break;
          }
          if (document.activeElement !== element) {
            element.focus();
          }
          await userEvent.click(element);
          break;
        }
        case "key": {
          focusTarget(step.target ?? "tree");
          await userEvent.keyboard(keyboardSyntax(step.key ?? ""));
          break;
        }
        case "type": {
          focusTarget(step.target ?? "tree");
          await userEvent.keyboard(step.text ?? "");
          break;
        }
        case "typeaheadReset":
          treeview.resetTypeahead();
          break;
        case "prop":
          mounted.setProp(step.prop ?? "", step.value);
          break;
        case "hover":
        case "unhover":
          break;
        default:
          throw new Error(`unsupported event ${step.event}`);
      }
      await settle();
    },
    observer: {
      focus: () => {
        const active = document.activeElement;
        if (!(active instanceof HTMLElement) || !root.contains(active)) {
          return null;
        }
        const part = active.closest<HTMLElement>('[data-part="treeview-item"]');
        return part === null ? "tree" : pathOf(part);
      },
      attr: (target, name) => {
        const value = elementOf(target).getAttribute(name);
        if (value === null) {
          return null;
        }
        if (value === "" && (name === "hidden" || name === "disabled")) {
          return "true";
        }
        return value;
      },
      visible: () =>
        items().flatMap((element) => {
          const path = pathOf(element);
          return path !== null && element.checkVisibility() ? [path] : [];
        }),
      events: (name) => {
        const fired = mounted.events.get(name) ?? [];
        if (!consumeEvents) {
          return fired;
        }
        const seen = consumed.get(name) ?? 0;
        consumed.set(name, fired.length);
        return fired.slice(seen);
      },
    },
    dispose: mounted.dispose,
  };
};

const dom = (config: ScenarioConfig) => treeviewDriver(mountTreeview(treeviewConfig(config)), true);

// The walk compares cumulative event lists after every step, like `specDriver`.
const domCumulative = (config: ScenarioConfig) =>
  treeviewDriver(mountTreeview(treeviewConfig(config)), false);

// Scenarios whose expectations the primitive deliberately does not meet. Each
// entry must still fail (so closing the gap forces removing it) and says why.
const FOCUS_ON_ENTRY =
  "APG focuses the selected node when the tree receives focus; the treeview spec (and the primitive) keep the roving node instead.";
const DIVERGENCES: Readonly<Record<string, string>> = {
  "treeview.apg.focus-selected-node": FOCUS_ON_ENTRY,
  "treeview.apg.focus-first-selected-node-multi-select": FOCUS_ON_ENTRY,
};

describe("Treeview x ported scenarios (real DOM)", () => {
  const file = parseScenarioFile(apg);
  describe(file.source, () => {
    for (const scenario of file.scenarios) {
      it(scenario.id, async (context) => {
        const run = replayScenario(scenario, treeviewBridge, dom);
        const divergence = DIVERGENCES[scenario.id];
        if (divergence !== undefined) {
          await expect(run).rejects.toBeInstanceOf(ScenarioMismatch);
          return;
        }
        const result = await run;
        if (result.status === "unsupported") {
          context.skip(result.reason);
        }
      });
    }
  });
});

describe("Treeview x spec (differential walk)", () => {
  const configs: ReadonlyArray<ScenarioConfig> = [
    {},
    { multiSelectable: true },
    {
      multiSelectable: true,
      expanded: ["0", "0/0"],
      selected: ["treeitem:1", "treeitem:0/0/1"],
      focus: "treeitem:0/0/0",
    },
    // controlled: a host that accepts every request, one that holds the value
    // (rejects), one that holds it in multi-select, and pinned values
    { controlled: true, accepts: true },
    { controlled: true, accepts: false },
    { controlled: true, accepts: true, multiSelectable: true },
    {
      controlled: true,
      accepts: true,
      expanded: ["0"],
      selected: ["treeitem:0/0"],
    },
    {
      controlled: true,
      accepts: false,
      expanded: ["0"],
      selected: ["treeitem:0/0"],
    },
  ];
  for (const config of configs) {
    it(`matches the generated model for ${JSON.stringify(config)}`, async () => {
      await differentialWalk({
        alphabet: treeviewSteps,
        probe: treeviewProbe,
        makePair: () =>
          Promise.resolve([specDriver(model, treeviewBridge, config), domCumulative(config)]),
        runs: 15,
        steps: 25,
        seed: 7,
      });
    });
  }
});

// The walk above is the primitive's contract through the skin's markup. What the skin adds is one part per row, the indent
// from `aria-level`, the selected row's fill, the chevron turned by `aria-expanded`, the hidden rows of a closed parent, and
// the DOM focus that follows the primitive's roving tabindex.
const style = (element: Element): CSSStyleDeclaration => getComputedStyle(element);
const token = (name: string): string => {
  const probe = document.createElement("div");
  probe.style.backgroundColor = `var(${name})`;
  document.body.append(probe);
  const value = style(probe).backgroundColor;
  probe.remove();
  return value;
};

/** Solid 2 delivers delegated events on a later turn. */
const tick = (): Promise<void> => new Promise((resolve) => setTimeout(resolve, 20));

const live: TreeviewMounted[] = [];
const mount = (config: ScenarioConfig = {}): TreeviewMounted => {
  const mounted = mountTreeview(treeviewConfig(config));
  live.push(mounted);
  return mounted;
};

afterEach(() => {
  for (const mounted of live.splice(0)) {
    mounted.dispose();
  }
});

const tree = (mounted: TreeviewMounted): HTMLElement =>
  mounted.root.querySelector<HTMLElement>('[data-part="treeview"]')!;
const rows = (mounted: TreeviewMounted): HTMLElement[] => [
  ...mounted.root.querySelectorAll<HTMLElement>('[data-part="treeview-item"]'),
];
/** The row of a spec node, by its id: the skin paints every row with the same part. */
const row = (mounted: TreeviewMounted, id: number): HTMLElement =>
  rows(mounted)[TREEVIEW_NODES.findIndex((node) => node.id === id)]!;
const chevron = (element: HTMLElement): HTMLElement =>
  element.querySelector<HTMLElement>(':scope > [aria-hidden="true"]')!;

describe("Treeview (the kit's look)", () => {
  it("is a named tree of rows, indented by the level the primitive announces", () => {
    const mounted = mount({ expanded: ["0"] });

    expect(tree(mounted).tagName).toBe("UL");
    expect(tree(mounted).getAttribute("data-part")).toBe("treeview");
    expect(tree(mounted).getAttribute("role")).toBe("tree");
    expect(tree(mounted).getAttribute("aria-label")).toBe("Files");
    expect(rows(mounted).every((element) => element.getAttribute("role") === "treeitem")).toBe(
      true,
    );
    expect(rows(mounted).every((element) => element.tagName === "LI")).toBe(true);

    // the level is the primitive's aria-level, and the skin's indent reads it (never a second copy)
    const projects = row(mounted, 1);
    const reports = row(mounted, 2);
    expect(projects.getAttribute("aria-level")).toBe("1");
    expect(reports.getAttribute("aria-level")).toBe("2");
    expect(parseFloat(style(reports).paddingInlineStart)).toBeGreaterThan(
      parseFloat(style(projects).paddingInlineStart),
    );
  });

  it("paints the selected row and turns the chevron from aria-expanded", async () => {
    const mounted = mount({ expanded: ["0"] });
    const projects = row(mounted, 1);
    const photos = row(mounted, 6);
    const resting = style(photos).backgroundColor;

    // an open parent's chevron is turned; a closed one's is not
    expect(projects.getAttribute("aria-expanded")).toBe("true");
    expect(row(mounted, 2).getAttribute("aria-expanded")).toBe("false");
    expect(style(chevron(projects)).transform).not.toBe("none");
    expect(style(chevron(row(mounted, 2))).transform).toBe("none");

    await userEvent.click(photos);
    await tick();

    expect(photos.getAttribute("aria-selected")).toBe("true");
    expect(projects.getAttribute("aria-selected")).toBe("false");
    expect(style(photos).backgroundColor).toBe(token("--color-button-background"));
    expect(style(photos).backgroundColor).not.toBe(resting);
  });

  it("does not paint the rows of a collapsed parent", () => {
    const mounted = mount();
    const reports = row(mounted, 2);

    // the primitive hides the row; the skin's own `display` must not override `[hidden]`
    expect(reports.hasAttribute("hidden")).toBe(true);
    expect(reports.checkVisibility()).toBe(false);
    expect(row(mounted, 1).checkVisibility()).toBe(true);
    expect(row(mounted, 6).checkVisibility()).toBe(true);
  });

  it("moves the real DOM focus to the row the primitive made roving", async () => {
    const mounted = mount();
    const projects = row(mounted, 1);
    const photos = row(mounted, 6);

    expect(projects.getAttribute("tabindex")).toBe("0");
    expect(photos.getAttribute("tabindex")).toBe("-1");

    projects.focus();
    projects.dispatchEvent(
      new KeyboardEvent("keydown", { key: "ArrowDown", bubbles: true, cancelable: true }),
    );
    flush();
    await tick();

    expect(document.activeElement).toBe(photos);
    expect(photos.getAttribute("tabindex")).toBe("0");
    expect(projects.getAttribute("tabindex")).toBe("-1");
    expect(mounted.treeview.focus()).toBe(6);
  });
});

import solid from "@solidjs/vite-plugin";
import cssints, { targets } from "cssints/vite";
import { defineConfig } from "vite-plus";
import { playwright } from "vite-plus/test/browser-playwright";

// The conformance test a starter arrives with runs in a real Chromium: the scenario walk needs a
// real DOM and Solid 2's reactivity, not a simulated one.
export default defineConfig({
  // `evaluation.inline`: a browser-mode runner inlines everything as ESM, so the plugin's own
  // evaluation server keeps the framework's packages inlined (Solid resolves its client build by
  // them) and the rest external (Node loads their CJS). Without it, a click's target resolves
  // against a second copy of Solid and the walk reads a state the page never changed.
  plugins: [
    cssints({ evaluation: { inline: ["solid-js", "@solidjs/web", "@solidjs/signals"] } }),
    solid(),
  ],
  css: { transformer: "lightningcss", lightningcss: { targets } },
  // The plugin adds `import derived from "cssints/derived"` to a client module after the dep
  // scanner has run; pre-bundling it here is what keeps that from reloading the page mid-test.
  optimizeDeps: { include: ["cssints/derived"] },
  test: {
    // a browser test has no app entry: the sheet of the modules the test imports arrives through
    // `virtual:cssints.css`, and vitest drops CSS imports unless it is told to process them
    css: true,
    // the sheet is loaded by the test's imports, not before them
    setupFiles: ["src/sheet.ts"],
    include: ["src/components/ui/**/*.browser.test.tsx"],
    browser: {
      enabled: true,
      provider: playwright(),
      headless: true,
      viewport: { width: 1280, height: 1024 },
      instances: [{ browser: "chromium" }],
      // The default waits 60 s for a worker's iframe to come up, which a busy machine (or a CI runner with a dozen other
      // jobs) misses: the run then fails as `the iframe did not become ready` with no test having run. Nothing about a
      // test gets longer; this is the browser starting.
      connectTimeout: 120_000,
      // the iframe ready timeout is read from the config's own env, not from the process that started the run
      env: { VITEST_BROWSER_IFRAME_TIMEOUT: "120000" },
    },
  },
});

// The engine's sheet for a browser test: its content is the CSS of the modules transformed so far, so it is loaded once the
// test file's imports are in (in `beforeAll`, not as a static import: vitest resolves the graph as it goes, and a sheet loaded
// first is just the `@layer` statement). A component's conformance test clicks its parts, so the sheet has to be there.
import { beforeAll } from "vite-plus/test";

beforeAll(async () => {
  await import("virtual:cssints.css");
});
